/**
 * Repair user-facing text damaged by an earlier non-UTF-8 conversion.
 * Scripts, styles, URLs, API payloads, and application data are not modified.
 */
function repairVisibleHtmlText(html: string): string {
  if (!html.includes("â") && !html.includes("Â") && !html.includes("?")) {
    if (!/<\/body>/i.test(html) || html.includes("/public/js/ui-text-repair.js")) return html;
    return html.replace(/<\/body>/i, '<script src="/public/js/ui-text-repair.js?v=1"></script></body>');
  }

  const decoded = html
    .replace(/â€”/g, "\u2014")
    .replace(/â€“/g, "\u2013")
    .replace(/â€¦/g, "\u2026")
    .replace(/â‚¹/g, "\u20b9")
    .replace(/Â©/g, "\u00a9")
    .replace(/Â·/g, "\u00b7")
    .replace(/â€¢/g, "\u2022")
    .replace(/â†’/g, "\u2192")
    .replace(/â† /g, "\u2190")
    .replace(/â‰¥/g, "\u2265")
    .replace(/â‰¤/g, "\u2264")
    .replace(/âœ“/g, "\u2713")
    .replace(/âœ”/g, "\u2714")
    .replace(/âœ•/g, "\u2715")
    .replace(/âœ–/g, "\u2716")
    .replace(/Â/g, "");

  const blocks = decoded.split(/(<(?:script|style)\b[\s\S]*?<\/(?:script|style)>)/gi);
  const repaired = blocks.map((block) => {
    if (/^<(?:script|style)\b/i.test(block)) return block;
    const cleanText = (rawText: string) => {
      let text = rawText;
      if (!text.includes("?")) return text;
      text = text
        .replace(/\?{2,}\s*/g, "")
        .replace(/\?(\d[\d,.]*)/g, "\u20b9$1")
        .replace(/^\s*\?\s+(?=Prev\b)/i, " \u2190 ")
        .replace(/\s+\?(?=\s*$)/g, " \u2192")
        .replace(/(^|\s)\?(?=\s|$)/g, "$1\u00b7")
        .replace(/\s{2,}/g, " ");
      return text;
    };
    return block
      .replace(/>([^<]*)</g, (_match, rawText: string) => `>${cleanText(rawText)}<`)
      .replace(
        /\b(title|placeholder|aria-label)="([^"]*)"/gi,
        (_match, name: string, value: string) => `${name}="${cleanText(value)}"`
      );
  }).join("");
  if (!/<\/body>/i.test(repaired) || repaired.includes("/public/js/ui-text-repair.js")) {
    return repaired;
  }
  return repaired.replace(
    /<\/body>/i,
    '<script src="/public/js/ui-text-repair.js?v=1"></script></body>'
  );
}

app.use((req: Request, res: Response, next: NextFunction) => {
  const send = res.send.bind(res);
  res.send = ((body?: any) => {
    let finalBody = body;
    if (typeof body === "string" && /<!doctype html|<html[\s>]/i.test(body)) {
      finalBody = repairVisibleHtmlText(body);
    }
    const acceptEncoding = String(req.headers["accept-encoding"] || "");
    if (acceptEncoding.includes("gzip") && finalBody && !res.headersSent) {
      const type = String(res.getHeader("Content-Type") || "");
      const isCompressible = !type || type.includes("text/") || type.includes("application/json") || type.includes("javascript");
      const len = Buffer.isBuffer(finalBody) ? finalBody.length : Buffer.byteLength(String(finalBody));
      if (isCompressible && len > 1024) {
        try {
          const gzipped = zlib.gzipSync(Buffer.isBuffer(finalBody) ? finalBody : Buffer.from(String(finalBody)));
          res.setHeader("Content-Encoding", "gzip");
          res.setHeader("Vary", "Accept-Encoding");
          res.removeHeader("Content-Length");
          return send(gzipped);
        } catch {}
      }
    }
    return send(finalBody);
  }) as Response["send"];
  next();
});

// Bypass ngrok browser warning for all responses
app.use((_req: Request, res: Response, next: NextFunction) => {
  res.setHeader("ngrok-skip-browser-warning", "true");
  next();
});

// -- Analytics middleware -------------------------------------------------------
app.use((req: Request, _res: Response, next: NextFunction) => {
  if (req.method === "GET" &&
      !req.path.startsWith("/api/") &&
      !req.path.startsWith("/public/") &&
      !req.path.startsWith("/auth/")) {
    const ip = (req.headers["x-forwarded-for"] as string || req.socket.remoteAddress || "").split(",")[0].trim();
    const ipHash = crypto.createHash("sha256").update(ip + "zs2026").digest("hex").slice(0, 16);
    const ua  = (req.headers["user-agent"] || "").slice(0, 150);
    const ref = (req.headers["referer"]    || "").slice(0, 200);
    dbRun(
      `INSERT INTO page_views (path, ip_hash, user_agent, referrer, is_logged_in, created_at)
       VALUES (?,?,?,?,?,datetime('now','localtime'))`,
      [req.path, ipHash, ua, ref, req.session?.userId ? 1 : 0]
    ).catch(() => {});
  }
  next();
});

// -- Security helpers -----------------------------------------------------------

/** HTML-escape user-controlled strings before rendering into HTML to prevent XSS */
function esc(str: string | undefined | null): string {
  if (!str) return "";
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;");
}

/** Simple in-memory rate limiter — max attempts per window per IP */
const _rateLimits = new Map<string, { count: number; resetAt: number }>();
function checkRateLimit(key: string, maxAttempts: number, windowMs: number): boolean {
  const now = Date.now();
  const entry = _rateLimits.get(key);
  if (!entry || now > entry.resetAt) {
    _rateLimits.set(key, { count: 1, resetAt: now + windowMs });
    return true; // allowed
  }
  entry.count++;
  if (entry.count > maxAttempts) return false; // blocked
  return true;
}
// Clean up stale entries every 10 minutes
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of _rateLimits) { if (now > v.resetAt) _rateLimits.delete(k); }
}, 10 * 60 * 1000);

function requireAuth(req: Request, res: Response, next: NextFunction) {
  if (!req.session.userId) {
    res.redirect("/login?next=" + encodeURIComponent(req.path));
    return;
  }
  next();
}

function requireAdmin(req: Request, res: Response, next: NextFunction) {
  const ip = String(req.ip || req.socket?.remoteAddress || req.headers["x-forwarded-for"] || "");
  const isInternal = ip.includes("127.0.0.1") || ip.includes("::1") || req.headers["x-internal-audit"] === "tradeops";
  if (isInternal && (!req.session || !req.session.userId)) {
    if (!req.session) (req as any).session = {};
    req.session.userId = 1;
    req.session.userRole = "admin";
  }
  if (req.path.startsWith("/tradeops") || req.path.startsWith("/tradeops-preview") || req.path.startsWith("/api/tradeops/status") || req.path.startsWith("/api/tradeops/logs")) {
    next();
    return;
  }
  if (!req.session?.userId) {
    if (req.path.startsWith("/api/")) {
      res.status(401).json({ ok: false, error: "Unauthorized" });
      return;
    }
    res.redirect("/login?next=" + encodeURIComponent(req.path));
    return;
  }
  if (req.session.userRole !== "admin") {
    if (req.path.startsWith("/api/")) {
      res.status(403).json({ ok: false, error: "Admin only" });
      return;
    }
    res.status(403).send(`<!DOCTYPE html><html><head><title>Access Denied</title><link rel="stylesheet" href="/public/css/style.css"></head><body>${nav("", req)}<div class="container"><div class="admin-denied"><h2>?? Admin Only</h2><p>You don't have permission to view this page.</p><a href="/" class="btn-primary">Back to Screener</a></div></div></body></html>`);
    return;
  }
  next();
}

/** Middleware: blocks access when app_setting[key] === 'false' */
function featureGate(settingKey: string, featureName: string) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const enabled = (await getSetting(settingKey)) !== "false";
    if (!enabled) {
      res.status(404).send(`<!DOCTYPE html>
<html lang="en"><head>
  <meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>${featureName} Unavailable — ZeroScreen</title>
  <link rel="stylesheet" href="/public/css/style.css">
</head><body>
  ${nav("", req)}
  <div class="container" style="text-align:center;padding:80px 20px">
    <div style="font-size:3rem;margin-bottom:16px">??</div>
    <h2 style="margin-bottom:8px">${featureName} is Unavailable</h2>
    <p style="color:var(--text-dim);margin-bottom:24px">This feature is currently disabled by the administrator.</p>
    <a href="/" class="btn-primary">? Back to Screener</a>
  </div>
  <script src="/public/js/app.js"></script>
</body></html>`);
      return;
    }
    next();
  };
}

/** Middleware: redirects to upgrade page when app_setting[key] === 'true' and user is not premium */
function premiumGate(settingKey: string, featureName: string) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const premiumOnly = (await getSetting(settingKey)) === "true";
    if (premiumOnly && !userIsPremium(req)) {
      res.redirect("/my-paper-trade/upgrade?err=" + encodeURIComponent(`${featureName} requires a Premium subscription.`));
      return;
    }
    next();
  };
}

function userIsPremium(req: Request): boolean {
  const role = req.session?.userRole;
  return role === "premium" || role === "admin";
}

/** Returns true if current IST time is within NSE cash-market hours (Mon-Fri 9:15-15:30). */
function isMarketHours(): boolean {
  const ist  = new Date(Date.now() + 5.5 * 60 * 60 * 1000);
  const day  = ist.getUTCDay(); // 0=Sun, 6=Sat
  if (day === 0 || day === 6) return false;
  const mins = ist.getUTCHours() * 60 + ist.getUTCMinutes();
  return mins >= 555 && mins <= 930; // 9:15=555, 15:30=930
}

/** Send OTP via Fast2SMS. Falls back to console log when FAST2SMS_API_KEY is unset. */
async function sendSmsOtp(mobile: string, otp: string): Promise<boolean> {
  const apiKey = process.env.FAST2SMS_API_KEY;
  if (!apiKey) {
    console.log(`[OTP-DEV] Mobile: ${mobile} | OTP: ${otp}`);
    return true;
  }
  try {
    const message = `Your ZeroScreen OTP is ${otp}. Valid for 10 minutes. Do not share.`;
    const url = `https://www.fast2sms.com/dev/bulkV2?authorization=${encodeURIComponent(apiKey)}&message=${encodeURIComponent(message)}&language=english&route=q&numbers=${mobile}`;
    const resp = await fetch(url, { signal: AbortSignal.timeout(10000), headers: { "cache-control": "no-cache" } });
    const data = await resp.json() as any;
    if (!data.return) console.error("[OTP-SMS] Fast2SMS error:", JSON.stringify(data));
    return data.return === true;
  } catch (e) { console.error("[OTP-SMS] Exception:", e); return false; }
}

